//! Color space types and conversions, re-implemented from the observed
//! behavior of the C++ `ColorSpace` library (single-precision arithmetic,
//! matching the reference binary's output byte-for-byte).

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        Rgb { r, g, b }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Yuv {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

impl Yuv {
    pub fn new(y: f32, u: f32, v: f32) -> Self {
        Yuv { y, u, v }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

impl Hsl {
    pub fn new(h: f32, s: f32, l: f32) -> Self {
        Hsl { h, s, l }
    }
}

pub struct ColorConverter;

impl ColorConverter {
    /// YUV -> RGB using the library's BT.601-style constants.
    pub fn yuv_to_rgb(yuv: &Yuv) -> Rgb {
        Rgb {
            r: yuv.y + 1.14 * yuv.v,
            g: yuv.y - 0.395 * yuv.u - 0.581 * yuv.v,
            b: yuv.y + 2.032 * yuv.u,
        }
    }

    /// RGB -> HSL, matching the library's branch structure exactly.
    pub fn rgb_to_hsl(rgb: &Rgb) -> Hsl {
        let r = rgb.r;
        let g = rgb.g;
        let b = rgb.b;

        let min = r.min(g).min(b);
        let max = r.max(g).max(b);
        let l = (max + min) / 2.0;

        if max == min {
            Hsl::new(0.0, 0.0, l)
        } else {
            let delta = max - min;
            let s = if l <= 0.5 {
                delta / (max + min)
            } else {
                delta / (2.0 - max - min)
            };

            let h = if max == r {
                (g - b) / delta + if g < b { 6.0 } else { 0.0 }
            } else if max == g {
                (b - r) / delta + 2.0
            } else {
                (r - g) / delta + 4.0
            };

            Hsl::new(h * 60.0, s, l)
        }
    }
}

//! Reproduces C++ `std::ostream << double` default formatting, i.e. printf's
//! `%g` with the default precision of 6 significant digits (trailing zeros
//! stripped, scientific notation outside the [-4, 6) exponent window).

/// Format an `f32` exactly as C++ `std::cout` would with default flags.
pub fn fmt_g(value: f32) -> String {
    let v = value as f64;

    if v.is_nan() {
        return if v.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf".to_string() } else { "inf".to_string() };
    }
    if v == 0.0 {
        return if v.is_sign_negative() { "-0".to_string() } else { "0".to_string() };
    }

    const P: i32 = 6; // default precision: 6 significant digits

    // Round to P significant digits in scientific form to learn the decimal
    // exponent of the *converted* value, as %g prescribes.
    let sci = format!("{:.*e}", (P - 1) as usize, v);
    let epos = sci.find('e').expect("scientific format always contains 'e'");
    let exp: i32 = sci[epos + 1..].parse().expect("valid exponent");

    if exp < -4 || exp >= P {
        // Scientific notation: strip trailing zeros from the mantissa and
        // emit the exponent with a sign and at least two digits (e-06).
        let mut mant = sci[..epos].to_string();
        if mant.contains('.') {
            while mant.ends_with('0') {
                mant.pop();
            }
            if mant.ends_with('.') {
                mant.pop();
            }
        }
        format!("{}e{}{:02}", mant, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        // Fixed notation with P - 1 - exp fractional digits, zeros stripped.
        let prec = (P - 1 - exp) as usize;
        let mut s = format!("{:.*}", prec, v);
        if s.contains('.') {
            while s.ends_with('0') {
                s.pop();
            }
            if s.ends_with('.') {
                s.pop();
            }
        }
        s
    }
}

use colorspace::color::{ColorConverter, Yuv};
use colorspace::fmt::fmt_g;

/// Mimics C++ `std::stof`: skips leading whitespace, parses the longest valid
/// float prefix (ignoring trailing garbage), and panics on invalid input just
/// as `std::stof` throws `std::invalid_argument`.
fn stof(s: &str) -> f32 {
    let t = s.trim_start();
    if let Ok(v) = t.parse::<f32>() {
        return v;
    }

    let bytes = t.as_bytes();
    let mut end = 0;

    // Optional sign.
    if end < bytes.len() && (bytes[end] == b'+' || bytes[end] == b'-') {
        end += 1;
    }
    // Integer and fractional digits with an optional single dot.
    let mut seen_digit = false;
    let mut seen_dot = false;
    while end < bytes.len() {
        match bytes[end] {
            b'0'..=b'9' => {
                seen_digit = true;
                end += 1;
            }
            b'.' if !seen_dot => {
                seen_dot = true;
                end += 1;
            }
            _ => break,
        }
    }
    // Optional exponent, only if the mantissa had digits.
    if seen_digit && end < bytes.len() && (bytes[end] == b'e' || bytes[end] == b'E') {
        let mut eend = end + 1;
        if eend < bytes.len() && (bytes[eend] == b'+' || bytes[eend] == b'-') {
            eend += 1;
        }
        let exp_start = eend;
        while eend < bytes.len() && bytes[eend].is_ascii_digit() {
            eend += 1;
        }
        if eend > exp_start {
            end = eend;
        }
    }

    if !seen_digit {
        // std::stof also accepts inf/infinity/nan (case-insensitive).
        let lower = t.to_ascii_lowercase();
        let neg = lower.starts_with('-');
        let body = lower.trim_start_matches(['+', '-']);
        for (name, val) in [
            ("infinity", f32::INFINITY),
            ("inf", f32::INFINITY),
            ("nan", f32::NAN),
        ] {
            if body.starts_with(name) {
                return if neg { -val } else { val };
            }
        }
        panic!("std::stof: no conversion could be performed");
    }

    t[..end].parse::<f32>().expect("scanned prefix is a valid float")
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut y: f32 = 0.5;
    let mut u: f32 = 0.2;
    let mut v: f32 = 0.3;

    if args.len() > 3 {
        y = stof(&args[1]);
        u = stof(&args[2]);
        v = stof(&args[3]);
    }

    let yuv = Yuv::new(y, u, v);
    let rgb = ColorConverter::yuv_to_rgb(&yuv);
    let hsl = ColorConverter::rgb_to_hsl(&rgb);

    println!(
        "{} {} {} {} {} {}",
        fmt_g(rgb.r),
        fmt_g(rgb.g),
        fmt_g(rgb.b),
        fmt_g(hsl.h),
        fmt_g(hsl.s),
        fmt_g(hsl.l)
    );
}

