// Brute-force HSL formula variants against the C++ binary.
fn fmt_g(value: f32) -> String {
    let v = value as f64;
    if v.is_nan() { return "nan".to_string(); }
    if v.is_infinite() { return if v < 0.0 { "-inf".into() } else { "inf".into() }; }
    if v == 0.0 { return if v.is_sign_negative() { "-0".into() } else { "0".into() }; }
    const P: i32 = 6;
    let sci = format!("{:.*e}", (P - 1) as usize, v);
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();
    if exp < -4 || exp >= P {
        let mut mant = sci[..epos].to_string();
        if mant.contains('.') {
            while mant.ends_with('0') { mant.pop(); }
            if mant.ends_with('.') { mant.pop(); }
        }
        format!("{}e{}{:02}", mant, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        let prec = (P - 1 - exp) as usize;
        let mut s = format!("{:.*}", prec, v);
        if s.contains('.') {
            while s.ends_with('0') { s.pop(); }
            if s.ends_with('.') { s.pop(); }
        }
        s
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let variant: u32 = args[1].parse().unwrap();
    let y: f32 = args[2].parse().unwrap();
    let u: f32 = args[3].parse().unwrap();
    let v: f32 = args[4].parse().unwrap();

    // Stage 1: confirmed pure f32
    let r = y + 1.14f32 * v;
    let g = y - 0.395f32 * u - 0.581f32 * v;
    let b = y + 2.032f32 * u;

    let (h, s, l): (f32, f32, f32);
    match variant {
        // v0: canonical, all f32, ((x/d)+adj)*60
        0 => {
            let mn = r.min(g).min(b);
            let mx = r.max(g).max(b);
            l = (mx + mn) / 2.0;
            if mx == mn { h = 0.0; s = 0.0; } else {
                let d = mx - mn;
                s = if l <= 0.5 { d / (mx + mn) } else { d / (2.0 - mx - mn) };
                let hh = if mx == r { (g - b) / d + if g < b { 6.0 } else { 0.0 } }
                    else if mx == g { (b - r) / d + 2.0 }
                    else { (r - g) / d + 4.0 };
                h = hh * 60.0;
            }
        }
        // v1: h = 60*(diff)/d + adj*60
        1 => {
            let mn = r.min(g).min(b);
            let mx = r.max(g).max(b);
            l = (mx + mn) / 2.0;
            if mx == mn { h = 0.0; s = 0.0; } else {
                let d = mx - mn;
                s = if l <= 0.5 { d / (mx + mn) } else { d / (2.0 - mx - mn) };
                h = if mx == r { 60.0 * (g - b) / d + if g < b { 360.0 } else { 0.0 } }
                    else if mx == g { 60.0 * (b - r) / d + 120.0 }
                    else { 60.0 * (r - g) / d + 240.0 };
            }
        }
        // v2: stage 2 in f64
        2 => {
            let (r, g, b) = (r as f64, g as f64, b as f64);
            let mn = r.min(g).min(b);
            let mx = r.max(g).max(b);
            let l64 = (mx + mn) / 2.0;
            if mx == mn { h = 0.0; s = 0.0; } else {
                let d = mx - mn;
                s = if l64 <= 0.5 { (d / (mx + mn)) as f32 } else { (d / (2.0 - mx - mn)) as f32 };
                let hh = if mx == r { (g - b) / d + if g < b { 6.0 } else { 0.0 } }
                    else if mx == g { (b - r) / d + 2.0 }
                    else { (r - g) / d + 4.0 };
                h = (hh * 60.0) as f32;
            }
            l = l64 as f32;
        }
        // v3: f32 but h = diff/d first, then *60, adj added after scaling
        3 => {
            let mn = r.min(g).min(b);
            let mx = r.max(g).max(b);
            l = (mx + mn) / 2.0;
            if mx == mn { h = 0.0; s = 0.0; } else {
                let d = mx - mn;
                s = if l <= 0.5 { d / (mx + mn) } else { d / (2.0 - mx - mn) };
                h = if mx == r { (g - b) / d * 60.0 + if g < b { 360.0 } else { 0.0 } }
                    else if mx == g { (b - r) / d * 60.0 + 120.0 }
                    else { (r - g) / d * 60.0 + 240.0 };
            }
        }
        // v4: f64 math for h only
        4 => {
            let mn = r.min(g).min(b);
            let mx = r.max(g).max(b);
            l = (mx + mn) / 2.0;
            if mx == mn { h = 0.0; s = 0.0; } else {
                let d = mx - mn;
                s = if l <= 0.5 { d / (mx + mn) } else { d / (2.0 - mx - mn) };
                let (r64, g64, b64, d64) = (r as f64, g as f64, b as f64, d as f64);
                let hh = if mx == r { (g64 - b64) / d64 + if g < b { 6.0 } else { 0.0 } }
                    else if mx == g { (b64 - r64) / d64 + 2.0 }
                    else { (r64 - g64) / d64 + 4.0 };
                h = (hh * 60.0) as f32;
            }
        }
        // v5: h via 60.0 * (diff / d) in f64 kept as f64 printed... need f64 print; skip
        _ => { h = 0.0; s = 0.0; l = 0.0; }
    }

    println!("{} {} {} {} {} {}", fmt_g(r), fmt_g(g), fmt_g(b), fmt_g(h), fmt_g(s), fmt_g(l));
}

