use std::fs;

fn fmt_g(value: f32) -> String {
    let v = value as f64;
    if v.is_nan() { return "nan".to_string(); }
    if v.is_infinite() { return if v < 0.0 { "-inf".into() } else { "inf".into() }; }
    if v == 0.0 { return if v.is_sign_negative() { "-0".into() } else { "0".into() }; }
    const P: i32 = 6;
    let sci = format!("{:.*e}", (P - 1) as usize, v);
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();
    if exp < -4 || exp >= P {
        let mut mant = sci[..epos].to_string();
        if mant.contains('.') {
            while mant.ends_with('0') { mant.pop(); }
            if mant.ends_with('.') { mant.pop(); }
        }
        format!("{}e{}{:02}", mant, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        let prec = (P - 1 - exp) as usize;
        let mut s = format!("{:.*}", prec, v);
        if s.contains('.') {
            while s.ends_with('0') { s.pop(); }
            if s.ends_with('.') { s.pop(); }
        }
        s
    }
}

// stage-1 g association
fn gvar(y: f32, u: f32, v: f32, gv: u32) -> f32 {
    match gv {
        0 => (y - 0.395f32 * u) - 0.581f32 * v,
        1 => y - (0.395f32 * u + 0.581f32 * v),
        2 => (y - 0.581f32 * v) - 0.395f32 * u,
        _ => unreachable!(),
    }
}

// stage-2 h shapes. Inputs: diffs and delta. adj: 0/6, 2, 4.
fn hvar(diff: f32, d: f32, adj: f32, neg_adj: bool, hv: u32) -> f32 {
    match hv {
        0 => (diff / d + adj) * 60.0,                 // ((g-b)/d + 6)*60
        1 => diff / d * 60.0 + adj * 60.0,            // (g-b)/d*60 + 360
        2 => 60.0 * diff / d + adj * 60.0,            // 60*(g-b)/d + 360
        3 => (diff + adj * d) / d * 60.0,             // ((g-b)+6d)/d*60
        4 => (diff + adj * d) * 60.0 / d,             // ((g-b)+6d)*60/d
        5 => { let h = diff / d * 60.0; if neg_adj { if h < 0.0 { h + 360.0 } else { h } } else { h + adj * 60.0 } },
        6 => { let h = diff * 60.0 / d; if neg_adj { if h < 0.0 { h + 360.0 } else { h } } else { h + adj * 60.0 } },
        // f64 math variants
        7 => (((diff as f64) / (d as f64) + adj as f64) * 60.0) as f32,
        8 => ((diff as f64) / (d as f64) * 60.0 + adj as f64 * 60.0) as f32,
        _ => unreachable!(),
    }
}

fn svar(d: f32, mx: f32, mn: f32, l: f32, sv: u32) -> f32 {
    match sv {
        0 => if l <= 0.5 { d / (mx + mn) } else { d / (2.0 - mx - mn) },
        1 => if l < 0.5 { d / (mx + mn) } else { d / (2.0 - mx - mn) },
        2 => { let l6 = l as f64; let d6 = d as f64;
