        let mut it = ln.split_whitespace();
        (it.next().unwrap().parse().unwrap(), it.next().unwrap().parse().unwrap(), it.next().unwrap().parse().unwrap())
    }).collect();
    let outs: Vec<&str> = cpp.lines().collect();

    let mut best = (usize::MAX, 0, 0, 0, 0);
    for gv in 0..3 {
