            for kr in -3i32..=3 { for kg in -3i32..=3 { for kb in -3i32..=3 {
                if kr == 0 && kg == 0 && kb == 0 { continue; }
                if compute(pert(r,kr), pert(g,kg), pert(b,kb)) == *out {
                    sols.push((kr, kg, kb));
                }
            }}}
            sols.sort_by_key(|s| s.0.abs() + s.1.abs() + s.2.abs());
            sols.truncate(4);
            println!("[{}] cpp={} sols={:?}", ln, out, sols);
        }
    }
