    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();
    if exp < -4 || exp >= P {
        let mut mant = sci[..epos].to_string();
        if mant.contains('.') { while mant.ends_with('0') { mant.pop(); } if mant.ends_with('.') { mant.pop(); } }
        format!("{}e{}{:02}", mant, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        let mut s = format!("{:.*}", (P - 1 - exp) as usize, v);
        if s.contains('.') { while s.ends_with('0') { s.pop(); } if s.ends_with('.') { s.pop(); } }
        s
    }
}
fn fmt_g(x: f32) -> String { fmt_g64(x as f64) }

// stage-1 model: 0 = pure f32; 1 = f64 math -> f32 store
fn stage1(y: f32, u: f32, v: f32, m: u32) -> (f32, f32, f32) {
    match m {
        0 => (y + 1.14f32 * v, y - 0.395f32 * u - 0.581f32 * v, y + 2.032f32 * u),
        1 => ((y as f64 + 1.14f64 * v as f64) as f32,
              (y as f64 - 0.395f64 * u as f64 - 0.581f64 * v as f64) as f32,
              (y as f64 + 2.032f64 * u as f64) as f32),
        _ => unreachable!(),
    }
}
// stage-2 model on f32 r,g,b; returns h as f32 (possibly via f64 paths)
fn stage2(r: f32, g: f32, b: f32, m: u32) -> (f32, f32, f32) {
    let mn = r.min(g).min(b); let mx = r.max(g).max(b);
    let l = (mx + mn) / 2.0;
    if mx == mn { return (0.0, 0.0, l); }
    let d = mx - mn;
    let s = if l <= 0.5 { d / (mx + mn) } else { d / (2.0 - mx - mn) };
    let (diff, adj) = if mx == r { (g - b, if g < b { 6.0f32 } else { 0.0 }) }
        else if mx == g { (b - r, 2.0) } else { (r - g, 4.0) };
    let q = diff / d;
    let h = match m {
        0 => (q + adj) * 60.0,
        1 => (((diff as f64) / (d as f64) + adj as f64) * 60.0) as f32,   // f64 all
        2 => (((diff as f64) / (mx as f64 - mn as f64) + adj as f64) * 60.0) as f32, // f64 exact delta
        3 => ((q as f64 + adj as f64) * 60.0) as f32,                     // f32 div, f64 rest
        4 => (diff + adj * d) / d * 60.0,
        5 => { // f64 quotient kept f64, +adj *60 in f64, no cast till print... emulate via f64 bits
            (((diff as f64) / (d as f64) + adj as f64) * 60.0) as f32
        }
        _ => unreachable!(),
    };
    (h, s, l)
}
fn main() {
    let corpus = fs::read_to_string("/tmp/corpus.txt").unwrap();
    let cpp = fs::read_to_string("/tmp/cpp_out.txt").unwrap();
    for m1 in 0..2 { for m2 in 0..5 {
        let mut fail = 0;
        for (ln, out) in corpus.lines().zip(cpp.lines()) {
            let mut it = ln.split_whitespace();
            let y: f32 = it.next().unwrap().parse().unwrap();
            let u: f32 = it.next().unwrap().parse().unwrap();
            let v: f32 = it.next().unwrap().parse().unwrap();
            let (r, g, b) = stage1(y, u, v, m1);
            let (h, s, l) = stage2(r, g, b, m2);
            let mine = format!("{} {} {} {} {} {}", fmt_g(r), fmt_g(g), fmt_g(b), fmt_g(h), fmt_g(s), fmt_g(l));
            if mine != out { fail += 1; }
        }
        println!("m1={} m2={}: {}/3000", m1, m2, fail);
    }}
}
